#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace FileCompass {
 internal static class WorkspacePolishTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();MainWindow main=null;CodeEditorWindow editor=null;AboutWindow about=null;try{
   Action<bool,string> check=delegate(bool ok,string text){if(!ok)throw new Exception(text);log.Add(text);};L.ChangeLanguage("cs");FluentTheme.Ensure();
   main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,Width=1740,Height=900,ShowActivated=false};main.Show();NavigationTests.WaitPanels(main);
   foreach(double width in new[]{1740.0,1280.0,960.0}){main.Width=width;main.UpdateLayout();NavigationTests.Wait(System.Threading.Tasks.Task.Delay(80));var toolbar=FluentUiTests.Children<Border>(main).Single(x=>Convert.ToString(x.Tag)=="main-toolbar-frame");var buttons=AdvancedToolsTests.Visual<Button>(toolbar).Where(x=>x.IsVisible).ToArray();check(buttons.Length>=17,"all original toolbar actions are visible at width "+width);foreach(var button in buttons){var at=button.TranslatePoint(new Point(),toolbar);check(at.X>=0&&at.X+button.ActualWidth<=toolbar.ActualWidth+1&&at.Y+button.ActualHeight<=toolbar.ActualHeight+1,"toolbar button fits after reflow: "+button.ToolTip+" / "+width);}var search=FluentUiTests.Children<TextBox>(main).Single(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="Hledat soubor");check(search.IsVisible&&search.TranslatePoint(new Point(search.ActualWidth,0),main).X<main.ActualWidth,"live search fits in the title row at width "+width);NextStageTests.Draw(main,Path.Combine(root,"toolbar-"+width+".png"));}
   editor=new CodeEditorWindow(main){Left=-18000,Top=-18000,Width=1200,Height=820,ShowActivated=false};editor.Show();var file=EditorTextFile.New();file.Path=Path.Combine(root,"Nastavení.json");file.Text="{\n  \"název\": \"File Compass\",\n  \"panely\": 2,\n  \"motiv\": \"Azur\"\n}\n";var doc=editor.Add(file);NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));editor.UpdateLayout();check(doc.Tab.IsVisible&&doc.Caption.IsVisible,"single document has a visible named tab");check(Math.Abs(doc.Editor.ActualWidth-editor.Tabs.ActualWidth)<1,"editor fills document workspace edge to edge");check(editor.Tabs.Parent is DockPanel&&editor.Tabs.Margin==new Thickness(0),"document workspace has no nested framed window or outer inset");var footer=FluentUiTests.Children<Border>(editor).Single(x=>Convert.ToString(x.Tag)=="dialog-footer");check(footer.ActualHeight<70,"status and actions share a compact footer");NextStageTests.Draw(editor,Path.Combine(root,"editor.png"));
   var other=EditorTextFile.New();other.Path=Path.Combine(root,"Poznámky.txt");other.Text="Druhý dokument";var second=editor.Add(other);editor.Tabs.SelectedItem=doc.Tab;editor.UpdateLayout();check(editor.Current==doc&&doc.Editor.Text.Contains("File Compass"),"switching document tabs preserves document text");NextStageTests.Draw(editor,Path.Combine(root,"editor-tabs.png"));editor.Width=800;editor.Height=600;editor.UpdateLayout();check(doc.Editor.ActualHeight>180&&footer.ActualHeight<70,"compact editor retains working space and footer actions");NextStageTests.Draw(editor,Path.Combine(root,"editor-compact.png"));foreach(var d in editor.Documents){d.Editor.IsModified=false;d.FormatModified=false;}editor.Close();editor=null;
   about=new AboutWindow(main){Left=-18000,Top=-18000,ShowActivated=false};about.Show();NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));check(about.DeveloperLogo.Parent is Grid,"developer logo is directly on the dialog background");var bitmap=new FormatConvertedBitmap((BitmapSource)about.DeveloperLogo.Source,PixelFormats.Bgra32,null,0);byte[] pixels=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];bitmap.CopyPixels(pixels,bitmap.PixelWidth*4,0);check(pixels[3]<32&&pixels[(bitmap.PixelWidth-1)*4+3]<32,"developer logo exterior has real alpha transparency");check(Enumerable.Range(0,pixels.Length/4).Count(i=>pixels[i*4+3]<32)>pixels.Length/16,"logo contains substantial transparent background");NextStageTests.Draw(about,Path.Combine(root,"about.png"));FluentColors.Select("mint");NavigationTests.Wait(System.Threading.Tasks.Task.Delay(60));NextStageTests.Draw(about,Path.Combine(root,"about-mint.png"));about.Close();about=null;main.Close();main=null;File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(about!=null)about.Close();if(editor!=null){foreach(var d in editor.Documents){d.Editor.IsModified=false;d.FormatModified=false;}editor.Close();}if(main!=null)main.Close();}}
 }
}
#endif
